From 7b355fd4d9858e70b7f1172819cdc54ff3512268 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 10:59:44 +0100
Subject: [PATCH] kded: also check disks that have no partition table

Only volumes holding a partition table were treated as devices, so a
disk encrypted or formatted as a whole was skipped and never checked
for SMART data. Also accept such volumes when they aren't partitions.

BUG: 499924
---
 src/soliddevicenotifier.cpp | 15 +++++++++++++++
 1 file changed, 15 insertions(+)

diff --git a/src/soliddevicenotifier.cpp b/src/soliddevicenotifier.cpp
index 303653f..746690c 100644
--- a/src/soliddevicenotifier.cpp
+++ b/src/soliddevicenotifier.cpp
@@ -6,6 +6,7 @@
 #include <Solid/Block>
 #include <Solid/DeviceInterface>
 #include <Solid/DeviceNotifier>
+#include <Solid/GenericInterface>
 #include <Solid/StorageDrive>
 #include <Solid/StorageVolume>

@@ -33,6 +34,15 @@ void SolidDeviceNotifier::checkUDI(const QString &udi)
     checkSolidDevice(Solid::Device(udi));
 }

+static bool isUnpartitionedDisk(const Solid::Device &device)
+{
+    const Solid::Device parent = device.parent();
+    if (!parent.is<Solid::StorageDrive>() || parent.as<Solid::StorageDrive>()->driveType() != Solid::StorageDrive::HardDisk) {
+        return false;
+    }
+    return !device.as<Solid::GenericInterface>()->propertyExists(QStringLiteral("Table"));
+}
+
 void SolidDeviceNotifier::checkSolidDevice(const Solid::Device &device)
 {
     qCDebug(KDED) << "!!!! " << device.udi();
@@ -59,6 +69,11 @@ void SolidDeviceNotifier::checkSolidDevice(const Solid::Device &device)
     case Solid::StorageVolume::Other:
         Q_FALLTHROUGH();
     case Solid::StorageVolume::Raid:
+        // A disk used without a partition table (e.g. encrypted as a whole)
+        // is still a device, as long as the volume isn't a partition.
+        if (isUnpartitionedDisk(device)) {
+            break;
+        }
         qCDebug(KDED) << "   bad type" << device.as<Solid::StorageVolume>()->usage();
         return;
     case Solid::StorageVolume::PartitionTable:
